body.query:
query Props($input: ProposalsInput!) {
  proposals(input: $input) {
    nodes { ... on Proposal {
      id onchainId status quorum createdAt chainId
      governor { id }
      start { ... on Block { number timestamp } ... on BlocklessTimestamp { timestamp } }
      end { ... on Block { number timestamp } ... on BlocklessTimestamp { timestamp } }
      voteStats { type votesCount votersCount percent }
      events { type createdAt }
      metadata { title description }
    } }
    pageInfo { lastCursor }
  }
}

metadata.description:
# Reduce Borrow Collateral Factor and Supply Caps for USDe to 0 on Ethereum
This proposal reduces the Collateral Factor utilized on borrow and Supply Caps for USDe; once executed, USDe on Ethereum markets can not be used as collateral for new loans. Note that this proposal will not directly trigger any liquidations as the liquidation collateral factor remains unchanged.

The proposal will minimize the potential risk of an rsETH hack in case it affects USDe.&#x20;
